//! Runtime schema of the immutable reviewed-content graph.
//!
//! These types are a *packet*, not the original memory model: every value is a
//! named identity or a semantic unit.  Source file names appear only in the
//! `resources` list; source addresses, LBAs and section offsets stay in the
//! reviewed inputs and in the extraction report.
//!
//! The asset is generated by the extraction pipeline and embedded
//! through the embedded campaign asset.

const std = @import("std");

pub const schema_id = "suikoden-campaign-content-graph/1";

pub const Package = struct {
    id: []const u8,
    role: []const u8,
    schema: []const u8,
    review: []const u8,
    commit: []const u8,
    asset_file_sha256: []const u8,
    asset_canonical_sha256: []const u8,
    proof_file_sha256: []const u8,
    scope: []const u8,
};

pub const Resource = struct {
    id: []const u8,
    file: []const u8,
    sha256: []const u8,
};

pub const HashConvention = struct {
    exact_file: []const u8,
    canonical_json: []const u8,
    section_digests: []const u8,
    items_digest: []const u8,
};

pub const Digests = struct {
    poses: []const u8,
    actions: []const u8,
    items: []const u8,
    formations: []const u8,
};

pub const Provenance = struct {
    packages: []const Package,
    resources: []const Resource,
};

/// Typed refusal carried by the reviewed inputs.  The reviewed prose stays in
/// the report; the runtime keeps the machine-readable code and typed operands.
pub const Blocker = struct {
    kind: []const u8,
    poses: ?[]const u32 = null,
    animations: ?[]const u32 = null,
    samples: ?u32 = null,
    opcode: ?u32 = null,
    track: ?[]const u8 = null,
};

pub const Page = struct {
    index: u32,
    slot: u32,
    width: u32,
    height: u32,
    sha256: []const u8,
};

pub const Palette = struct {
    index: u32,
    words: u32,
    sha256: []const u8,
};

pub const Anchor = struct {
    x: i32,
    y: i32,
};

pub const Piece = struct {
    page: u32,
    palette: u32,
    u: u32,
    v: u32,
    width: u32,
    height: u32,
    x: ?i32 = null,
    y: ?i32 = null,
    flip_x: bool,
    flip_y: bool,
    cross_page_samples: u32,
    outside_samples: u32,
};

pub const Pose = struct {
    index: u32,
    width: u32,
    height: u32,
    anchor: Anchor,
    pieces: []const Piece,
};

pub const Frame = struct {
    pose: u32,
    ticks: u32,
};

pub const Animation = struct {
    index: u32,
    frames: []const Frame,
    resolved: bool = true,
    missing_poses: []const u32 = &.{},
};

pub const PageBinding = struct {
    index: u32,
    sha256: []const u8,
};

pub const PaletteBinding = struct {
    index: u32,
    words: u32,
    sha256: []const u8,
};

pub const Admission = struct {
    mechanics_complete: bool,
    reaction_resolved: bool,
    residency_qualified: bool,

    pub fn complete(self: Admission) bool {
        return self.mechanics_complete and self.reaction_resolved and self.residency_qualified;
    }
};

/// The party-action identity, bound to the sprite residency it was compiled against.
/// Execution data (timeline events, boundaries, audio cues) belongs to the
/// `campaign_policies.party_actions` adapter; this packet binds action identity and its allowed poses.
pub const Action = struct {
    family: []const u8,
    status: []const u8,
    required_animations: []const u32,
    binding_sha256: []const u8,
    pages: []const PageBinding,
    palettes: []const PaletteBinding,
    poses: []const Pose,
    animations: []const Animation,
    admission: Admission,
    blockers: []const Blocker,
};

pub const Character = struct {
    id: []const u8,
    resource: []const u8,
    residency_status: []const u8,
    script_domain_complete: bool,
    pages: []const Page,
    palettes: []const Palette,
    poses: []const Pose,
    animations: []const Animation,
    action_poses: []const u32,
    action_animations: []const u32,
    blockers: []const Blocker,
    action: ?Action = null,
};

pub const Stats = struct {
    power: u16,
    skill: u16,
    defense: u16,
    speed: u16,
    magic: u16,
    luck: u16,
};

pub const Item = struct {
    id: []const u8,
    source_item_id: u16,
    label: []const u8,
    category: []const u8,
    price: u32,
    max_uses: u8,
    usable: bool,
    requires_target: bool,
    battle_usable: bool,
    appraisal_tier: u8,
    equipment_slot: ?[]const u8 = null,
    equipment_type_mask: u8,
    weapon_fragment: ?[]const u8 = null,
    duplicate_label: bool,
    supported_ops: []const []const u8,
