pub const Category = struct {
    id: []const u8,
    count: u32,
    ownership: []const u8,
    description: []const u8,
};

pub const EventOperation = struct {
    effect: []const u8,
    engine_rule: ?[]const u8 = null,
    status: ?[]const u8 = null,
};

pub const ItemEngine = struct {
    shared_capacity: u8,
    duplicate_acquisition: []const u8,
    append: []const u8,
    remove: []const u8,
    query: []const u8,
    transfer_predicate: []const u8,
    event_operations: []const EventOperation,
};

pub const DuplicateGroup = struct {
    label: []const u8,
    items: []const []const u8,
};

pub const TrailingLabel = struct {
    id: []const u8,
    label: []const u8,
};

pub const Fragment = struct {
    element: []const u8,
    id: []const u8,
    source_item_id: u16,
};

pub const Identity = struct {
    stable_id_policy: []const u8,
    duplicate_label_groups: []const DuplicateGroup,
    trailing_space_labels: []const TrailingLabel,
    weapon_fragments: []const Fragment,
};

pub const ItemCatalogue = struct {
    schema: []const u8,
    source_main_file_sha256: []const u8,
    source_main_image_sha256: []const u8,
    digest: []const u8,
    categories: []const Category,
    engine: ItemEngine,
    identity: Identity,
    blockers: []const Blocker,
};

pub const Drop = struct {
    item: ?u16 = null,
    rate: u8,
};

pub const Scan = struct {
    front_only: bool,
    draw_kind: []const u8,
    accept_at_least: u8,
};

pub const SecondDraw = struct {
    kind: []const u8,
    threshold: u8,
};

/// Only the policy class and the disposition of its effect are bound here.
/// The source resource identities with embedded offsets remain in the
/// reviewed enemy-policy asset for `campaign_policies.enemy_policy`.
pub const Special = struct {
    kind: []const u8,
    target_required: bool,
    wait_frames: u16,
    effect_kind: []const u8,
    effect_blocker: ?Blocker = null,
};

pub const Policy = struct {
    family: []const u8,
    scan: ?Scan = null,
    second_draw: ?SecondDraw = null,
    own_row_front_below: ?u8 = null,
    target_row_front_below: ?u8 = null,
    no_selection: ?[]const u8 = null,
    special: ?Special = null,
    blocker: ?Blocker = null,
};

pub const Enemy = struct {
    id: []const u8,
    name: []const u8,
    level: u8,
    formation_footprint: u8,
    hp: u16,
    stats: Stats,
    element_coefficients: [6]u8,
    feature_flags: u16,
    money_encoded: i16,
    drops: []const Drop,
    policy: Policy,
};

pub const Slot = struct {
    roster_id: u8,
    enemy: ?[]const u8 = null,
    x: i32,
    y: i32,
    z: i32,
};

pub const Formation = struct {
    id: []const u8,
    active: u8,
    slots: []const Slot,
};

pub const Area = struct {
    id: []const u8,
    label: []const u8,
    enemies: []const Enemy,
    formations: []const Formation,
};

pub const DropItem = struct {
    id: u16,
    default_uses: u8,
};

/// Spell presentation is an exact typed dependency: the reviewed correction is absent, so this
/// record refuses every spell presentation join instead of defaulting one.
pub const SpellPresentation = struct {
    status: []const u8,
    package: []const u8,
    code: []const u8,
    owner: []const u8,
    required_interface: []const u8,
    detail: []const u8,
};

pub const Graph = struct {
    schema: []const u8,
    revision: []const u8,
    hash_convention: HashConvention,
    provenance: Provenance,
    digests: Digests,
    characters: []const Character,
    items: []const Item,
    item_catalogue: ItemCatalogue,
    drop_items: []const DropItem,
    areas: []const Area,
    spell_presentation: SpellPresentation,
};

pub const Mode = enum {
    title,
    field,
    menu,
    battle,
    world,
};

pub const Name = struct {
    pub const capacity = 48;
    bytes: [capacity]u8 = @splat(0),
    len: u8 = 0,

    pub fn init(text: []const u8) error{NameTooLong}!Name {
        if (text.len > capacity) return error.NameTooLong;
        var name: Name = .{};
        @memcpy(name.bytes[0..text.len], text);
        name.len = @intCast(text.len);
        return name;
    }

    pub fn slice(self: *const Name) []const u8 {
        return self.bytes[0..self.len];
    }

    pub fn eql(self: *const Name, other: *const Name) bool {
        return std.mem.eql(u8, self.slice(), other.slice());
    }
};
